const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
async function render(){const name=new URLSearchParams(location.search).get('team');if(!name){$('#team-content').innerHTML='<p class="empty">Choose a team from the Team Race standings.</p>';return}try{const feed=await fetch('/api/public/team-race',{cache:'no-store'}).then(r=>r.ok?r.json():Promise.reject()),team=(feed.teams||[]).find(item=>item.team===name);if(!team)throw Error();document.title=`${team.team} · OWAR 2026`;$('#team-content').innerHTML=`<section class="rider-hero team-hero"><div><div class="eyebrow">Team Race</div><h1>${esc(team.team)}</h1><p>Position ${esc(team.position)} · ${esc(team.elapsed)}</p></div></section><section class="rider-stats"><div><span>Official laps</span><strong>${esc(team.official_laps)}</strong>${team.penalty?`<small class="penalty-label">Penalty: ${esc(team.penalty)}</small>`:''}</div><div><span>Fastest lap</span><strong>${esc(team.fastest_lap||'—')}</strong></div></section><section class="race-table history-card"><div class="history-heading"><span>Team Race</span><h2>Lap timings</h2></div><div class="table-scroll"><table><thead><tr><th>Lap</th><th>Rider</th><th>Time</th></tr></thead><tbody>${(team.laps||[]).map(lap=>`<tr><td>Lap ${esc(lap.lap_number)}</td><td>${lap.athlete_id?`<a class="rider rider-link" href="/rider/?id=${encodeURIComponent(lap.athlete_id)}">`:'<span class="rider">'}<span class="bib">${esc(lap.rider_bib||'—')}</span><span class="name">${esc(lap.rider_name)}</span>${lap.athlete_id?'</a>':'</span>'}</td><td class="time">${esc(lap.time)}</td></tr>`).join('')||'<tr><td colspan="3">No laps recorded.</td></tr>'}</tbody></table></div></section>`}catch{$('#team-content').innerHTML='<p class="empty">This team is not available yet.</p>'}}
render();
